// packages/learning/src/self-test/index.ts
//
// Golden self-test (plan §5.1.6).
//
// Embeds fixed Arabic and English sentences and compares against reference
// vectors stored in the repo. Cosine >= 0.98 passes (tolerates CPU
// differences). Also verifies that a sentence is closer to its translation
// than to an unrelated sentence — the cross-lingual sanity check that
// catches a broken or wrong-language model.
//
// The reference vectors are committed alongside this file. They were
// generated by `bun run tl:selftest:freeze` against a known-good int8
// model on x86-64 glibc. Different CPUs may differ slightly, hence the
// 0.98 threshold rather than exact equality.

import { Effect, Schema } from "effect"
import golden from "./golden.json"

// ---------------------------------------------------------------------------
// Reference fixtures
// ---------------------------------------------------------------------------

export const GoldenCase = Schema.Struct({
  id: Schema.String,
  text: Schema.String,
  language: Schema.Literals(["ar", "en"]),
  // Stored as Float32Array-base64 (4 bytes per float, 1024 floats).
  referenceVectorB64: Schema.String,
  // Optional: another case id this one should be closer to than to a random one.
  closerTo: Schema.optional(Schema.String),
  furtherFrom: Schema.optional(Schema.String),
})
export type GoldenCase = Schema.Schema.Type<typeof GoldenCase>

/** Golden Arabic/English sentences and reference vectors; frozen by scripts/freeze-selftest.ts. */
export const GOLDEN_CASES = golden.cases as GoldenCase[]

// ---------------------------------------------------------------------------
// Cosine similarity
// ---------------------------------------------------------------------------

export const cosine = (a: Float32Array, b: Float32Array): number => {
  if (a.length !== b.length) {
    throw new Error(`vector length mismatch: ${a.length} vs ${b.length}`)
  }
  let dot = 0
  let normA = 0
  let normB = 0
  for (let i = 0; i < a.length; i++) {
    const av = a[i]!
    const bv = b[i]!
    dot += av * bv
    normA += av * av
    normB += bv * bv
  }
  const denom = Math.sqrt(normA) * Math.sqrt(normB)
  return denom === 0 ? 0 : dot / denom
}

// ---------------------------------------------------------------------------
// b64 <-> Float32Array
// ---------------------------------------------------------------------------

export const vectorToB64 = (vec: Float32Array): string => {
  const bytes = new Uint8Array(vec.buffer, vec.byteOffset, vec.byteLength)
  let binary = ""
  for (let i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]!)
  return btoa(binary)
}

export const b64ToVector = (b64: string, expectedLength = 1024): Float32Array => {
  const binary = atob(b64)
  const bytes = new Uint8Array(binary.length)
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i)
  const vec = new Float32Array(bytes.buffer)
  if (vec.length !== expectedLength) {
    throw new Error(`expected ${expectedLength} floats, got ${vec.length}`)
  }
  return vec
}

// ---------------------------------------------------------------------------
// Self-test
// ---------------------------------------------------------------------------

export class SelfTestError extends Schema.TaggedErrorClass<SelfTestError>()(
  "TargetedLearning.SelfTestError",
  {
    message: Schema.String,
    caseId: Schema.optional(Schema.String),
  },
) {}

export interface SelfTestReport {
  totalCases: number
  passedCases: number
  cosineScores: Array<{ caseId: string; cosine: number }>
  crossLingualPassed: boolean
  details: string[]
}

const SIMILARITY_THRESHOLD = 0.98

/**
 * Run the golden self-test using an embedding function.
 * The embedding function is provided by the caller (the EmbedPipeline)
 * so this module stays free of the Transformers.js dependency.
 */
export const runSelfTest = (
  embed: (text: string) => Effect.Effect<Float32Array, unknown>,
): Effect.Effect<SelfTestReport, SelfTestError, never> =>
  Effect.gen(function* () {
    const report: SelfTestReport = {
      totalCases: GOLDEN_CASES.length,
      passedCases: 0,
      cosineScores: [],
      crossLingualPassed: false,
      details: [],
    }

    // Step 1: vectors not frozen yet?
    if (GOLDEN_CASES.some((c) => !c.referenceVectorB64)) {
      return yield* Effect.fail(
        new SelfTestError({
          message:
            "Golden vectors are not yet frozen. Run `bun run tl:selftest:freeze` after the runtime spike passes.",
        }),
      )
    }

    // Step 2: embed each case and compare to reference.
    const embedded = new Map<string, Float32Array>()
    for (const case_ of GOLDEN_CASES) {
      const vec = yield* embed(case_.text).pipe(
        Effect.mapError(
          (err) =>
            new SelfTestError({
              message: `embed failed for ${case_.id}: ${String(err).slice(0, 200)}`,
              caseId: case_.id,
            }),
        ),
      )
      embedded.set(case_.id, vec)
      const reference = b64ToVector(case_.referenceVectorB64, vec.length)
      const score = cosine(vec, reference)
      report.cosineScores.push({ caseId: case_.id, cosine: score })
      if (score >= SIMILARITY_THRESHOLD) {
        report.passedCases++
        report.details.push(`✓ ${case_.id}: cosine=${score.toFixed(4)}`)
      } else {
        report.details.push(`✗ ${case_.id}: cosine=${score.toFixed(4)} (need >= ${SIMILARITY_THRESHOLD})`)
      }
    }

    // Step 3: cross-lingual sanity check.
    for (const case_ of GOLDEN_CASES) {
      if (!case_.closerTo || !case_.furtherFrom) continue
      const vec = embedded.get(case_.id)!
      const closer = embedded.get(case_.closerTo)!
      const further = embedded.get(case_.furtherFrom)!
      const scoreCloser = cosine(vec, closer)
      const scoreFurther = cosine(vec, further)
      if (scoreCloser > scoreFurther) {
        report.crossLingualPassed = true
        report.details.push(
          `✓ cross-lingual: ${case_.id} closer to ${case_.closerTo} (${scoreCloser.toFixed(4)}) than to ${case_.furtherFrom} (${scoreFurther.toFixed(4)})`,
        )
      } else {
        report.details.push(
          `✗ cross-lingual: ${case_.id} NOT closer to ${case_.closerTo} (${scoreCloser.toFixed(4)}) than to ${case_.furtherFrom} (${scoreFurther.toFixed(4)})`,
        )
      }
    }

    if (report.passedCases < report.totalCases) {
      return yield* Effect.fail(
        new SelfTestError({
          message: `Self-test failed: ${report.passedCases}/${report.totalCases} cases passed.`,
        }),
      )
    }
    if (!report.crossLingualPassed) {
      return yield* Effect.fail(
        new SelfTestError({ message: "Cross-lingual sanity check failed." }),
      )
    }
    return report
  })
